; EXODUS.BIN: Ultima III (Origin 1983, PC version by James R. Van Artsdalen).
; Generated by tools/gen.py; tools/build.py builds it (MASM, LINK, then the image from 0100).
; ENDING: the move count and the end of the game (A46F-A5AC).
;
; PrintMoves: the move counter, printed by Quit & Save (LOOP 1F35) and at the end.
; EndGame: reached from ACTIONS (76BC) when Exodus is destroyed: "Congratulations!
; Thou hast compleated Exodus: Ultima 3 in N moves", the map window flashed 21 times, the
; final text in the map window, then a key and the program stops in an endless loop (PARTY
; Hang: jmp to itself). Two helpers of the town services follow (used only by TOWNS):
; AskYesNo and PayGold.
; The texts are in TEXT.ASM (MsgMoves-MsgEndLine10, EndFlashPatterns at EndFlashPatterns).
CODE SEGMENT BYTE PUBLIC
ASSUME CS:CODE, DS:CODE, ES:CODE, SS:CODE
EXTRN KeyReady:NEAR
EXTRN ReadKey:NEAR
EXTRN PrintBcdByte:NEAR
EXTRN AskChoice:NEAR
EXTRN PrintAt:NEAR
EXTRN Sound:NEAR
EXTRN Location:BYTE
EXTRN MoveCount:BYTE
EXTRN PrintMsg:NEAR
EXTRN ScrollMsg:NEAR
EXTRN ClearView:NEAR
EXTRN SaveGame:NEAR
EXTRN Hang:NEAR
EXTRN YesNoMenuKeys:BYTE
EXTRN YesNoMenuStrs:BYTE
EXTRN EndFlashPatterns:BYTE
EXTRN MsgMoves:BYTE
EXTRN MsgCongratulations:BYTE
EXTRN MsgReportThyFeat:BYTE
EXTRN MsgEndLine1:BYTE
EXTRN MsgEndLine2:BYTE
EXTRN MsgEndLine3:BYTE
EXTRN MsgEndLine4:BYTE
EXTRN MsgEndLine5:BYTE
EXTRN MsgEndLine6:BYTE
EXTRN MsgEndLine7:BYTE
EXTRN MsgEndLine8:BYTE
EXTRN MsgEndLine9:BYTE
EXTRN MsgEndLine10:BYTE
PUBLIC PrintMoves
PUBLIC EndGame
PUBLIC AskYesNo
PUBLIC PayGold
;------------------------------------------------------------------------------
; PrintMoves: print MoveCount as 8 BCD digits, most significant byte first, then
; " moves" and a new line. Uses: nothing (saves AX, CX, SI, flags).
;------------------------------------------------------------------------------
PrintMoves:	pushf	;@A46F
	push ax	;@A470
	push cx	;@A471
	push si	;@A472
	std	; backwards	;@A473
	lea si, MoveCount	;@A474
	add si, 3	; from the top byte (MoveCount+3)	;@A478
	mov cx, 4	;@A47B
PrintMoves_Loop:	lodsb	;@A47E
	call PrintBcdByte	; two digits	;@A47F
	loop PrintMoves_Loop	;@A482
	cld	;@A484
	lea si, MsgMoves	; " moves"	;@A485
	call PrintMsg	;@A489
	pop si	;@A48C
	pop cx	;@A48D
	pop ax	;@A48E
	popf	;@A48F
	ret	;@A490
;------------------------------------------------------------------------------
; XorMapWindow: XOR the word AX into the map window: 58h pairs of scan lines (both CGA banks)
; of 16h words (176 x 176 pixels) from offset 142h (x 8, y 8); like PARTY FlashView with a pattern.
; In: AX = the pattern. Uses: nothing.
;------------------------------------------------------------------------------
XorMapWindow:	pushf	;@A491
	push bx	;@A492
	push cx	;@A493
	push dx	;@A494
	push ds	;@A495
	mov ds, word ptr ds:[4F39h]	; the CGA screen segment (ScreenSeg, library K25A9 = 4F39h here)	;@A496
	mov bx, 142h	; scan line 8 (4 x 80 bytes), pixel 8 (byte 2)	;@A49A
	mov dx, 58h	; 58h lines (x 2 banks)	;@A49D
XorMapWindow_Line:	mov cx, 16h	; 16h words: 176 pixels	;@A4A0
XorMapWindow_Word:	xor word ptr [bx], ax	;@A4A3
	xor word ptr [bx+2000h], ax	; the odd scan line	;@A4A5
	inc bx	;@A4A9
	inc bx	;@A4AA
	loop XorMapWindow_Word	;@A4AB
	add bx, 24h	; to the next line (80 bytes)	;@A4AD
	dec dx	;@A4B0
	jne XorMapWindow_Line	;@A4B1
	pop ds	;@A4B3
	pop dx	;@A4B4
	pop cx	;@A4B5
	pop bx	;@A4B6
	popf	;@A4B7
	ret	;@A4B8
;------------------------------------------------------------------------------
; EndGame: the end of the game, after Exodus is destroyed (ACTIONS 76BC). Prints the
; congratulations and the move count, flashes the map window with the 21 patterns of
; EndFlashPatterns (a sound each), writes the final text (MsgEndLine1-10) at rows 3-15h of
; the map window, waits for a key and hangs. Never returns.
;------------------------------------------------------------------------------
EndGame:	lea si, MsgCongratulations	;@A4B9
	call PrintMsg	;@A4BD
	call PrintMoves	; PrintMoves	;@A4C0
	lea si, MsgReportThyFeat	;@A4C3
	call PrintMsg	;@A4C7
	cld	;@A4CA
	lea si, EndFlashPatterns	;@A4CB
	mov cx, 15h	; 21 patterns	;@A4CF
EndGame_Flash:	mov al, 0F7h	; sound 0F7h	;@A4D2
	call Sound	;@A4D4
	lodsw	;@A4D7
	call XorMapWindow	;@A4D8
	loop EndGame_Flash	;@A4DB
	call ClearView	;@A4DD
	mov dh, 3	; row 3, column 5	;@A4E0
	mov dl, 5	;@A4E2
	lea si, MsgEndLine1	;@A4E4
	call PrintAt	;@A4E8
	mov dh, 5	; then rows 5, 7, ... 15h at column 2	;@A4EB
	mov dl, 2	;@A4ED
	lea si, MsgEndLine2	;@A4EF
	call PrintAt	;@A4F3
	mov dh, 7	;@A4F6
	mov dl, 2	;@A4F8
	lea si, MsgEndLine3	;@A4FA
	call PrintAt	;@A4FE
	mov dh, 9	;@A501
	mov dl, 2	;@A503
	lea si, MsgEndLine4	;@A505
	call PrintAt	;@A509
	mov dh, 0Bh	;@A50C
	mov dl, 2	;@A50E
	lea si, MsgEndLine5	;@A510
	call PrintAt	;@A514
	mov dh, 0Dh	;@A517
	mov dl, 2	;@A519
	lea si, MsgEndLine6	;@A51B
	call PrintAt	;@A51F
	mov dh, 0Fh	;@A522
	mov dl, 2	;@A524
	lea si, MsgEndLine7	;@A526
	call PrintAt	;@A52A
	mov dh, 11h	;@A52D
	mov dl, 2	;@A52F
	lea si, MsgEndLine8	;@A531
	call PrintAt	;@A535
	mov dh, 13h	;@A538
	mov dl, 2	;@A53A
	lea si, MsgEndLine9	;@A53C
	call PrintAt	;@A540
	mov dh, 15h	;@A543
	mov dl, 2	;@A545
	lea si, MsgEndLine10	;@A547
	call PrintAt	;@A54B
	call SaveGame	; ? (PARTY: depends on Location)	;@A54E
	mov byte ptr Location, 1	; Location = 1 (dungeon) ?why	;@A551
EndGame_WaitKey:	call KeyReady	;@A556
	je EndGame_WaitKey	;@A559
	call ReadKey	;@A55B
	jmp Hang	; PARTY Hang: jmp to itself, the end	;@A55E
;------------------------------------------------------------------------------
; AskYesNo: read Y, N, Q or Esc (library AskChoice, printing "Yes" or "No") and scroll
; the message window. Out: AL = 'Y' (59h) or 'N' (4Eh) for any other key. Uses: nothing else.
;------------------------------------------------------------------------------
AskYesNo:	pushf	;@A561
	push cx	;@A562
	push ax	;@A563
	push si	;@A564
	push di	;@A565
	mov cx, 4	; four keys	;@A566
	lea si, YesNoMenuStrs	; YesNoMenuStrs (TEXT)	;@A569
	lea di, YesNoMenuKeys	; YesNoMenuKeys: "YNQ", Esc	;@A56D
	call AskChoice	;@A571
	call ScrollMsg	;@A574
	cmp al, 59h	; 'Y'	;@A577
	je AskYesNo_Done	;@A579
	mov al, 4Eh	; 'N' for N, Q and Esc	;@A57B
AskYesNo_Done:	pop di	;@A57D
	pop si	;@A57E
	mov cl, al	; keep AL past the pop of AX	;@A57F
	pop ax	;@A581
	mov al, cl	;@A582
	pop cx	;@A584
	popf	;@A585
	ret	;@A586
;------------------------------------------------------------------------------
; PayGold: take AX (a BCD price) off the gold of the player at DI. In: DI = record,
; AX = price. Out: CF set if his gold [di+23h] is less (nothing taken), else gold -= price,
; CF clear. AX kept. The compare is binary, which orders BCD words correctly, so the borrow
; case (gold set to 0) cannot happen.
;------------------------------------------------------------------------------
PayGold:	xchg word ptr [di+23h], ax	; AX = gold, [di+23h] = price	;@A587
	cmp ax, word ptr [di+23h]	; gold < price?	;@A58A
	xchg word ptr [di+23h], ax	; swap back (flags kept)	;@A58D
	jb PayGold_Done	; CF: not enough	;@A590
	xchg word ptr [di+23h], ax	; AX = gold again	;@A592
	sub al, byte ptr [di+23h]	; gold - price, low byte (BCD)	;@A595
	das	;@A598
	xchg al, ah	;@A599
	sbb al, byte ptr [di+24h]	; high byte with borrow	;@A59B
	das	;@A59E
	xchg al, ah	;@A59F
	xchg word ptr [di+23h], ax	; gold = the rest, AX = price	;@A5A1
	jae PayGold_Done	;@A5A4
	mov word ptr [di+23h], 0	; not reached (see above)	;@A5A6
PayGold_Done:	ret	;@A5AB
CODE ENDS
END
